arguments.new_string:
if alignment == '<':
    regex += '(.+?)'
elif alignment == '>':
    regex += ' *(.+?)'
elif alignment == '^':
    regex += ' *(.+?) *'

arguments.old_string:
if alignment == '<':
    regex += '(.+?)[^ ]*'
elif alignment == '>':
    regex += ' *(.+?)'
elif alignment == '^':
    regex += ' *(.+?)[^ ]*'
